* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
body {
  background: #0d0603;
  font-family: 'Georgia', 'Times New Roman', serif;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}
.container {
  width: 1280px;
  height: 720px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  position: relative;
}
/* 背景微光 */
.container::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(212, 168, 83, 0.06) 0%, transparent 70%);
  pointer-events: none;
}
.title {
  color: #f5e6c8;
  font-size: 32px;
  font-weight: bold;
  letter-spacing: 4px;
  margin-bottom: 10px;
  opacity: 0;
  animation: fadeIn 0.6s ease forwards;
}
.subtitle {
  color: #b8956a;
  font-size: 14px;
  margin-bottom: 40px;
  opacity: 0;
  animation: fadeIn 0.6s ease 0.2s forwards;
}
.pie-svg {
  width: 400px;
  height: 400px;
  opacity: 0;
  animation: fadeIn 0.8s ease 0.4s forwards;
}
/* 扇形样式 */
.slice-path {
  stroke: #0d0603;
  stroke-width: 2;
  stroke-linejoin: round;
  opacity: 0;
  transform-origin: 200px 200px;
  animation: sliceGrow 0.6s ease forwards;
}
@keyframes sliceGrow {
  from {
    opacity: 0;
    transform: scale(0.8);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
/* 扇形上的百分比文字 */
.slice-text {
  fill: #f5e6c8;
  font-size: 14px;
  font-weight: bold;
  opacity: 0;
  animation: fadeIn 0.4s ease forwards;
  text-shadow: 0 1px 3px rgba(0,0,0,0.8);
}
/* 图例 */
.legend {
  display: flex;
  gap: 30px;
  margin-top: 40px;
}
.legend-item {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #d4a853;
  font-size: 13px;
  opacity: 0;
  transform: translateY(10px);
  animation: legendUp 0.4s ease forwards;
}
.legend-dot {
  width: 14px;
  height: 14px;
  border-radius: 3px;
}
@keyframes fadeIn {
  to { opacity: 1; }
}
@keyframes legendUp {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}结尾后3秒（作为收尾数据总结）统一的纸雕灯风格美学，用相同的美术风格处理数据展示，配上和数据相关的tts语音对齐语音和bgm

